import unittest

from report import body, footer, header, normalize_name


class TestReport(unittest.TestCase):
    def test_shapes(self):
        self.assertEqual(header(' Alice '), '[ alice ]')
        self.assertEqual(footer(' Bob '), '( bob )')
        self.assertEqual(body(' Carol '), '  carol')

    def test_helper(self):
        self.assertEqual(normalize_name(' Dave '), 'dave')


if __name__ == '__main__':
    unittest.main()
